package studio.jiayu.neoagent;
import android.app.Activity;import android.os.*;import android.widget.*;import android.view.accessibility.*;import org.json.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.atomic.*;
/** Native model-to-MCP-to-executor test; mock provider, zero external sockets. */
final class McpContracts {
 static void yes(boolean b,String m)throws Exception{if(!b)throw new Exception(m);}
 static JSONObject req(int id,String method)throws Exception{return new JSONObject().put("jsonrpc","2.0").put("id",id).put("method",method);}
 static JSONObject init()throws Exception{return req(1,"initialize").put("params",new JSONObject().put("protocolVersion",DeviceMcp.VERSION).put("clientInfo",new JSONObject().put("name","owned-test").put("version","1")).put("capabilities",new JSONObject()));}
 static String call(String tool,JSONObject args)throws Exception{return req(1,"tools/call").put("params",new JSONObject().put("name",tool).put("arguments",args)).toString();}
 static void start(Activity a){TextView note=new TextView(a);note.setText("本机MCP回归");a.setContentView(note);new Handler().postDelayed(()->new Thread(()->run(a)).start(),800);}
 static void run(Activity a){ControlService s=ControlService.instance;JSONObject out=new JSONObject();String before="";boolean scopeChanged=false;int passed=0;AtomicInteger requests=new AtomicInteger();AtomicBoolean feedbackSeen=new AtomicBoolean();try{
 yes(s!=null&&s.connected&&!s.busy(),"Runtime unavailable");DeviceMcp m=new DeviceMcp(s);yes(m.rpc(req(1,"tools/list"),0).getJSONObject("error").getInt("code")==-32002,"Tools accepted before initialization");passed++;
 yes(m.rpc(init(),0).getJSONObject("result").getString("protocolVersion").equals(DeviceMcp.VERSION),"Version negotiation missing");passed++;
 yes(m.rpc(req(2,"tools/list"),0).has("error"),"Tools accepted before initialized notification");passed++;
 m.rpc(new JSONObject().put("jsonrpc","2.0").put("method","notifications/initialized"),0);yes(m.initialized,"Initialized notification ignored");passed++;
 JSONArray catalog=m.rpc(req(3,"tools/list"),0).getJSONObject("result").getJSONArray("tools");Set<String> names=new HashSet<>();for(int i=0;i<catalog.length();i++){JSONObject t=catalog.getJSONObject(i);yes(!t.getString("name").isEmpty()&&t.getJSONObject("inputSchema").getBoolean("additionalProperties")==false&&names.add(t.getString("name")),"Invalid or duplicate catalog entry");}passed++;
 yes(names.containsAll(Arrays.asList("document.focus","document.replace","purchase.check","purchase.submit","purchase.pay","skills.read")),"Current native tools absent");passed++;
 yes(m.rpc(req(4,"resources/list"),0).getJSONObject("result").getJSONArray("resources").length()==5,"Skill resources missing");passed++;
 JSONObject resource=m.rpc(req(5,"resources/read").put("params",new JSONObject().put("uri","neo-skill://commerce")),0);yes(resource.getJSONObject("result").getJSONArray("contents").getJSONObject(0).getString("text").contains("purchase.check"),"Wrong bundled commerce skill");passed++;
 yes(m.rpc(req(6,"resources/read").put("params",new JSONObject().put("uri","file:///private")),0).has("error"),"Arbitrary file resource accepted");passed++;
 yes(m.rpc(req(7,"resources/read"),0).has("error"),"Malformed resource request not rejected");passed++;
 yes(m.rpc(new JSONObject().put("jsonrpc","2.0").put("method","tools/call").put("params",new JSONObject().put("name","device.back")),0).has("error"),"Notification executed as a tool");passed++;
 for(String raw:new String[]{call("device.tap",new JSONObject().put("id",1.5)),call("device.type",new JSONObject().put("text","x").put("shell","ignored")),call("skills.read",new JSONObject().put("id","../../private"))}){boolean denied=false;try{DeviceMcp.decode(raw);}catch(Exception expected){denied=true;}yes(denied,"Invalid MCP arguments accepted");passed++;}
 yes(DeviceMcp.decode(call("device.submit_search",new JSONObject())).name.equals("submit_search"),"System editor search schema missing");passed++;
 yes(DeviceMcp.decode(call("skills.read",new JSONObject().put("id","documents"))).name.equals("skills_read"),"Skill identifier treated as node number");passed++;
 yes(DeviceMcp.decode("{\"action\":\"tap\",\"id\":\"6\"}").data.getInt("id")==6,"Legacy numeric-string compatibility lost");passed++;
 for(Exception error:new Exception[]{new ControlService.UiChangedException(),new ControlService.KeyboardOcclusionException(),new ControlService.LocalBoundaryException("owned boundary")}){JSONObject detail=new JSONObject().put("structuredContent",new JSONObject().put("errorCategory",DeviceMcp.errorCategory(error)));yes(DeviceMcp.toolFailure(detail,"owned boundary").getClass()==error.getClass(),"Typed recovery exception lost");passed++;}
 before=new Vault(a).get(RoutineAccess.KEY);Config cfg=new Config();cfg.endpoint="https://fixture.invalid/v1";cfg.key="LOCAL_FIXTURE";cfg.vision=true;cfg.maxSteps=8;new RoutineAccess(a).approve(cfg,Collections.singletonList(a.getPackageName()));scopeChanged=true;
 URL.setURLStreamHandlerFactory(protocol->protocol.equals("https")?new URLStreamHandler(){protected URLConnection openConnection(URL url){return new ModelContracts.Fake(url){public InputStream getInputStream(){try{int turn=requests.incrementAndGet();JSONObject request=new JSONObject(body.toString("UTF-8"));String text=request.getJSONArray("messages").getJSONObject(1).getJSONArray("content").getJSONObject(0).getString("text");JSONObject state=new JSONObject(text.substring(text.lastIndexOf("当前界面：")+5));String response;if(turn==1)response=call("skills.list",new JSONObject());else if(turn==2)response=call("skills.read",new JSONObject().put("id","documents"));else if(turn==3){feedbackSeen.set(text.contains("skills_list")&&text.contains("skills_read")&&!s.pendingDispatch);JSONArray nodes=state.getJSONArray("nodes");int id=-1;for(int i=0;i<nodes.length();i++)if(nodes.getJSONObject(i).optBoolean("editable"))id=nodes.getJSONObject(i).getInt("id");response=call("device.type",new JSONObject().put("id",id).put("text","mcp recovery"));}else response="{\"action\":\"finish\",\"message\":\"本机MCP验证\"}";return new ByteArrayInputStream(new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("message",new JSONObject().put("content",response)))).toString().getBytes("UTF-8"));}catch(Exception e){return new ByteArrayInputStream("{}".getBytes());}}};}}:null);
 yes(s.ui(()->s.start(cfg,a.getPackageName(),"在本地演示中输入mcp recovery，检查后结束")),"Native MCP goal failed to start");long until=SystemClock.elapsedRealtime()+30000;while(s.busy()&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);yes(!s.busy()&&!s.paused&&requests.get()==4&&s.actions==3,"MCP goal did not finish expected native sequence");passed++;
 yes(feedbackSeen.get(),"Read-only skills calls left uncertain mutation checkpoint");passed++;
 boolean actual=s.ui(()->{AccessibilityNodeInfo root=s.getRootInActiveWindow();if(root==null)return false;for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText("mcp recovery"))if(n.isEditable()&&"mcp recovery".contentEquals(n.getText()))return true;return false;});yes(actual,"MCP type did not reach actual native input");passed++;
 yes(s.deviceMcp.toolCalls==3&&s.deviceMcp.lastTool.equals("device.type")&&s.deviceMcp.initialized,"Runtime bypassed MCP adapter");passed++;
 out.put("success",true).put("mock_model_requests",requests.get()).put("tool_calls",s.deviceMcp.toolCalls).put("native_text_verified",actual).put("catalog_count",catalog.length());
 }catch(Throwable e){try{out.put("success",false).put("failure",e.getMessage());}catch(Exception ignored){}}finally{if(s!=null)s.stop("MCP回归结束");try{if(scopeChanged){if(before.isEmpty())new Vault(a).remove(RoutineAccess.KEY);else new Vault(a).put(RoutineAccess.KEY,before);out.put("scope_restored",before.equals(new Vault(a).get(RoutineAccess.KEY)));}try(FileOutputStream f=a.openFileOutput("mcp-contracts.json",0)){f.write(out.put("passed",passed).put("real_network_calls",0).put("external_listener",false).put("third_party_actions",0).put("sampledAt",System.currentTimeMillis()).toString(2).getBytes("UTF-8"));}}catch(Exception ignored){}a.runOnUiThread(a::finish);}}
}
